507			if statErr != nil || lstatErr != nil || current.Mode()&os.ModeSymlink != 0 || !current.Mode().IsRegular() || !os.SameFile(opened, current) || !artifactPathWithin(NativeFiles(), root.path, path) {
508				cleanup()
