225	func reviewExecutableDigestWithin(path string, maxBytes int64) (string, error) {
226		if maxBytes <= 0 || maxBytes > reviewExecutableMaxBytes {
227			return "", fmt.Errorf("invalid provenance executable byte bound")
228		}
229		// Resolve the observed target for hashing; execution retains the selected
230		// path spelling so relative and shebang argv0 semantics stay unchanged.
231		resolved, e := filepath.EvalSymlinks(path)
232		if e != nil {
233			return "", e
234		}
235		info, e := os.Lstat(resolved)
236		if e != nil || !info.Mode().IsRegular() || info.Size() < 0 || info.Size() > maxBytes {
237			return "", fmt.Errorf("provenance executable is not a bounded regular file")
238		}
239		f, e := os.Open(resolved)
240		if e != nil {
241			return "", e
242		}
243		opened, e := f.Stat()
244		if e != nil || !os.SameFile(info, opened) {
245			f.Close()
246			return "", fmt.Errorf("executable changed while opening")
247		}
248		hash := sha256.New()
249		n, e := io.Copy(hash, io.LimitReader(f, maxBytes+1))
250		closeErr := f.Close()
251		if e != nil || closeErr != nil || n > maxBytes {
252			return "", fmt.Errorf("executable digest could not be read within bound")
253		}
254		return "sha256:" + hex.EncodeToString(hash.Sum(nil)), nil
255	}
