51	func withGovernanceReadViewCaptureAttempt(s Store, producer string, attempt int, allowMissingPrimaryRevision bool, run func(Store) (bool, error)) error {
52		base, view := s.beginGovernanceReadView(allowMissingPrimaryRevision)
53		store := base.withGovernanceReadView(view, producer).PinIndexes()
54		if !allowMissingPrimaryRevision {
55			_, _ = captureGovernanceSourceRevision(store.fsys(), store.Root, producer)
56		}
57		requiresPrimaryRevision, err := run(store)
58		if err != nil {
59			// A callback can translate a failed read into a domain error. Preserve
60			// that error and the independently audited closure failure, without
61			// retrying a callback that has already failed.
62			audit := view.audit()
63			auditErr := governanceReadViewUnknownError(audit)
64			if governanceReviewAuditChanged(audit) {
65				auditErr = errors.Join(auditErr, ErrGovernanceReadViewChanged)
66			}
67			if auditErr == nil {
68				return err
69			}
70			return errors.Join(err, auditErr)
71		}
72		if requiresPrimaryRevision {
73			view.operation.requirePrimaryRevision(producer)
74		}
75		audit := view.audit()
76		changed := governanceReviewAuditChanged(audit)
77		if changed && attempt == 0 {
78			return withGovernanceReadViewCaptureAttempt(base.withoutGovernanceReadView(), producer, 1, allowMissingPrimaryRevision, run)
79		}
80		if changed {
81			return ErrGovernanceReadViewChanged
82		}
83		return governanceReadViewUnknownError(audit)
84	}
