86	// Summaries contain producer labels and audit reasons, excluding observed paths
87	// and the underlying path-bearing details of root/index resolution failures.
88	func governanceReadViewUnknownError(audit governanceReadViewAudit) error {
89		if len(audit.UnknownProducers) > 0 {
90			producers := make([]string, 0, len(audit.UnknownProducers))
91			for producer := range audit.UnknownProducers {
92				producers = append(producers, producer)
93			}
94			sort.Strings(producers)
95			clip := func(value string, limit int) string {
96				if len(value) <= limit {
97					return value
98				}
99				return value[:limit-3] + "..."
100			}
101			var summary strings.Builder
102			for i, producer := range producers {
103				if i >= 8 {
104					fmt.Fprintf(&summary, "; ... %d more producer(s)", len(producers)-i)
105					break
106				}
107				if i > 0 {
108					summary.WriteString("; ")
109				}
110				summary.WriteString(clip(producer, 128))
111				summary.WriteString(": ")
112				reasons := append([]string(nil), audit.UnknownProducers[producer]...)
113				sort.Strings(reasons)
114				for j, reason := range reasons {
115					if j >= 4 {
116						fmt.Fprintf(&summary, "; ... %d more reason(s)", len(reasons)-j)
117						break
118					}
119					if j > 0 {
120						summary.WriteString(" | ")
121					}
122					for _, prefix := range []string{"index generation could not be pinned:", "authorized roots could not be resolved:"} {
123						if strings.HasPrefix(reason, prefix) {
124							reason = strings.TrimSuffix(prefix, ":")
125							break
126						}
127					}
128					summary.WriteString(clip(reason, 256))
129				}
130			}
131			detail := summary.String()
132			if len(detail) > 2048 {
133				detail = detail[:2045] + "..."
134			}
135			return fmt.Errorf("%w: %d producer(s) lack a complete observation: %s", ErrGovernanceReadViewUnknown, len(audit.UnknownProducers), detail)
136		}
137		return nil
138	}
